"""Prepare publication copies of the complete Lab 1 session exports."""

import json
from pathlib import Path
import re
import subprocess


ROOT = Path(__file__).resolve().parent
SOURCE = ROOT / "Laboratorium 1" / "sesje"
DESTINATION = ROOT / "lab1" / "sesje"
PRIVATE_EMAIL = re.compile(
    r"(?<![\\a-z0-9._%+\-])[a-z0-9._%+\-]{1,128}"
    r"@(?:gmail\.com|outlook\.com|hotmail\.com|wp\.pl|onet\.pl)"
    r"(?![a-z0-9.\-])",
    re.IGNORECASE,
)


def git_setting(key):
    result = subprocess.run(
        ["git", "config", "--get", key], cwd=ROOT,
        capture_output=True, text=True, check=False,
    )
    return result.stdout.strip() if result.returncode == 0 else ""


def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings(item)
    elif isinstance(value, list):
        for item in value:
            yield from strings(item)


def transform(value, replace):
    if isinstance(value, str):
        return replace(value)
    if isinstance(value, dict):
        return {key: transform(item, replace) for key, item in value.items()}
    if isinstance(value, list):
        return [transform(item, replace) for item in value]
    return value


def main():
    sources = sorted(SOURCE.glob("*.jsonl"))
    if len(sources) != 6:
        raise RuntimeError("Expected exactly six source session exports.")
    sessions = {
        path.name: [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines()]
        for path in sources
    }
    private_emails = {
        match.group(0)
        for events in sessions.values()
        for event in events
        for text in strings(event)
        for match in PRIVATE_EMAIL.finditer(text)
    }
    configured_email = git_setting("user.email")
    if configured_email:
        private_emails.add(configured_email)
    identity = git_setting("user.name")
    identity_pattern = re.compile(
        r"(?:(?<![/\w])|(?<=\\n)|(?<=\\r)|(?<=\\t))"
        + re.escape(identity) + r"(?!\w)", re.IGNORECASE,
    ) if identity else None

    def replace(text):
        for email in sorted(private_emails, key=len, reverse=True):
            text = text.replace(email, "[ADRES_EMAIL_UKRYTY]")
        if identity_pattern is not None:
            text = identity_pattern.sub("[DANE_AUTORA_UKRYTE]", text)
        return text

    DESTINATION.mkdir(parents=True, exist_ok=True)
    for name, events in sessions.items():
        sanitized = [transform(event, replace) for event in events]
        output = "".join(json.dumps(event, ensure_ascii=False, separators=(",", ":")) + "\n" for event in sanitized)
        (DESTINATION / name).write_bytes(output.encode("utf-8"))
        print(f"Publication export: {name}; preserved events: {len(events)}")


if __name__ == "__main__":
    main()

