'ranks':r'(?i)\b(?:[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY]|[TYTUL_UKRYTY])\.?\b|[TYTUL_UKRYTY]\w*|[TYTUL_UKRYTY]\w*|[TYTUL_UKRYTY]\w*|[TYTUL_UKRYTY]\w*',
'identity':r'(?i)imi[eę]\s*[:=]|nazwisk\w*|stopie[nń]|whiskey\s+alpha\s+tango|[DANE_OSOBOWE_UKRYTE]|przemys[lł]aw'
}
for label,expression in patterns.items():
    pattern=re.compile(expression)
    matches=[]
    for path in sorted((root/'lab1').rglob('*')):
        if not path.is_file():continue
        content=path.read_text(encoding='utf-8')
        found=list(pattern.finditer(content))
        if found:
            examples=[]
            for m in found:
                context=content[max(0,m.start()-45):m.end()+60]
                if context not in examples:examples.append(context)
                if len(examples)==2:break
            matches.append({'file':str(path.relative_to(root)),'occurrences':len(found),'examples':examples})
    print(json.dumps({'category':label,'matches':matches},ensure_ascii=False))
print('CLI',json.dumps({name:shutil.which(name) for name in ('git','gh','python')},ensure_ascii=False))
for path in sorted((root/'Laboratorium 1'/'sesje').glob('*.jsonl')):
    counts=collections.Counter()
    def inspect(value):
        if isinstance(value,dict):
            if value.get('type') in ('image','input_image','image_url'):counts[value['type']]+=1
            for key,item in value.items():
                if key in ('image_url','image_path'):counts[key]+=1
                inspect(item)
        elif isinstance(value,list):
